INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sollten Präsentationen immer mit Text überladen sein?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit und Übersichtlichkeit sind wichtiger"}, {"text": "Ja", "correct": false, "because": "Überladung verwirrt Zuhörer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel einer guten Präsentation?', 3, '[{"text": "Klar vermitteln", "correct": true, "because": "Zuhörer sollen Inhalte verstehen"}, {"text": "Maximale Länge", "correct": false, "because": "Kürze ist effektiver"}, {"text": "Manuelle Gestik", "correct": false, "because": "Natürlichkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern eine Präsentation?', 5, '[{"text": "Visuelle Hilfsmittel", "correct": true, "because": "Veranschaulichen Inhalte"}, {"text": "Klare Struktur", "correct": true, "because": "Führt Zuhörer durch"}, {"text": "Übermäßige Animationen", "correct": false, "because": "Lenken ab"}, {"text": "Unlesbare Schrift", "correct": false, "because": "Erschwert Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Weniger Text pro Folie ist besser. b) Bunte Folien sind immer ansprechend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann überladen wirken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Gestaltung einer Präsentation?', 4, '[{"text": "Zielgruppenanalyse", "correct": false, "because": "Passt Inhalte an"}, {"text": "Lesbarkeit", "correct": false, "because": "Sichert Verständnis"}, {"text": "Musikwiedergabe", "correct": true, "because": "Meist unpassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Folie animiert sein sollte?', 2, '[{"text": "Nein", "correct": true, "because": "Animationen sparsam einsetzen"}, {"text": "Ja", "correct": false, "because": "Übermäßige Animationen ablenken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, die Aufmerksamkeit zu halten?', 3, '[{"text": "KISS-Prinzip", "correct": true, "because": "Keep It Simple, Stupid fördert Klarheit"}, {"text": "Maximaler Text", "correct": false, "because": "Überfordert Zuhörer"}, {"text": "Manuelle Übergänge", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen eine Präsentation professionell?', 5, '[{"text": "Einheitliches Design", "correct": true, "because": "Wirkt konsistent"}, {"text": "Wenige Farben", "correct": true, "because": "Vermeidet Chaos"}, {"text": "Viele Schriftarten", "correct": false, "because": "Wirkt unruhig"}, {"text": "Lange Texte", "correct": false, "because": "Erschweren Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bilder unterstützen Inhalte. b) Jede Folie braucht Animationen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) lenkt oft ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine gute Präsentation?', 4, '[{"text": "Klarer Aufbau", "correct": false, "because": "Leitet Zuhörer"}, {"text": "Verständliche Sprache", "correct": false, "because": "Fördert Klarheit"}, {"text": "Überladene Folien", "correct": true, "because": "Verwirren Zuhörer"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sollten Folien viel Text enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Kürze erhöht Verständnis"}, {"text": "Ja", "correct": false, "because": "Textflut überfordert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken fördern die Verständlichkeit?', 4, '[{"text": "Stichpunkte", "correct": true, "because": "Strukturieren Inhalte"}, {"text": "Diagramme", "correct": true, "because": "Veranschaulichen Daten"}, {"text": "Winzige Schrift", "correct": false, "because": "Schwer lesbar"}]'),
('00000000-0000-0000-000000000000', 'Habe gehört, dass jede Präsentation gleich gestaltet sein sollte. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassung an Zielgruppe nötig"}, {"text": "Ja", "correct": false, "because": "Flexibilität wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Vorbereitung einer Präsentation?', 3, '[{"text": "Zielgruppenfokus", "correct": true, "because": "Passt Inhalte an"}, {"text": "Viele Effekte", "correct": false, "because": "Lenken ab"}, {"text": "Manuelle Folien", "correct": false, "because": "Vorlagen effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kontrastreiche Farben helfen Lesbarkeit. b) Alle Folien brauchen Bilder.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine klare Struktur?', 5, '[{"text": "Besseres Verständnis", "correct": true, "because": "Leitet Zuhörer"}, {"text": "Leichtere Nachvollziehbarkeit", "correct": true, "because": "Fördert Klarheit"}, {"text": "Viele Animationen", "correct": false, "because": "Lenken ab"}, {"text": "Komplexe Folien", "correct": false, "because": "Verwirren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Präsentation unwichtig?', 3, '[{"text": "Lesbare Schrift", "correct": false, "because": "Sichert Verständnis"}, {"text": "Konsistenz", "correct": false, "because": "Fördert Professionalität"}, {"text": "Zufällige Hintergründe", "correct": true, "because": "Stören Einheitlichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Präsentation immer Bilder benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Inhalte stehen im Fokus"}, {"text": "Ja", "correct": false, "because": "Bilder sind optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sollte ich viele Farben in einer Präsentation nutzen?', 3, '[{"text": "Nein", "correct": true, "because": "Wenige Farben wirken klarer"}, {"text": "Ja", "correct": false, "because": "Viele Farben verwirren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Präsentationsregeln?', 4, '[{"text": "Vorstellung eines IT-Projekts", "correct": true, "because": "Klarheit und Struktur nötig"}, {"text": "Musikwiedergabe", "correct": false, "because": "Andere Domäne"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
